#[test]
fn parity_sign_zeros() {
    for rec in load_scenarios("sign_estimate.json") {
        if rec["scenario"] == "sign_zeros" {
            let x = flat_f64(&rec["inputs"]["x"]);
            let got = core::sign_estimate(&x);
            let expected = flat_i8(&face_rec(&rec, "numpy-reference").unwrap()["signs"]);
            assert_eq!(got, expected, "sign_zeros vs numpy-reference");
            assert!(!got.contains(&0), "no output value may be 0");
            let zeros: Vec<f64> = flat_f64(&rec["inputs"]["all_zeros"]);
            let gz = core::sign_estimate(&zeros);
            assert!(gz.iter().all(|&v| v == 1), "all-zero input maps to +1");
            if let Some(pyo3) = face_rec(&rec, "pyo3") {
                assert_eq!(got, flat_i8(&pyo3["signs"]), "sign_zeros face parity");
            }
        }
    }
}

