// ---------------------------------------------------------------------------
// packed matvec / matmul scenarios
// ---------------------------------------------------------------------------

#[test]
fn parity_matvec_padded() {
    for rec in load_scenarios("packed_matvec.json") {
        if rec["scenario"] == "matvec_padded" {
            let packed = flat_u8(&rec["inputs"]["packed"]);
            let dirty = flat_u8(&rec["inputs"]["packed_dirty"]);
            let vec = flat_f64(&rec["inputs"]["vec"]);
            let n_bits = rec["dtypes"]["n_bits"].as_u64().unwrap() as usize;
            let rows = shape2(&shape_of(&rec["inputs"]["packed"])).0;
            let got = core::packed_matvec(&packed, rows, n_bits, &vec).expect("matvec");
            let numpy_rec = flat_f64(&face_rec(&rec, "numpy-reference").unwrap()["result"]);
            assert_rel(&got, &numpy_rec, "matvec_padded vs numpy-reference");
            assert_f64_bitidentical(&got, &numpy_rec, "matvec_padded bit-identical");
            // dirty pad bits contribute exactly 0 (bit-identical output)
            let got_dirty = core::packed_matvec(&dirty, rows, n_bits, &vec).expect("matvec dirty");
            let numpy_dirty = flat_f64(&face_rec(&rec, "numpy-reference").unwrap()["result_dirty"]);
            assert_f64_bitidentical(&got_dirty, &numpy_dirty, "matvec dirty pad bit-identical");
            if let Some(pyo3) = face_rec(&rec, "pyo3") {
                assert_rel(
                    &got,
                    &flat_f64(&pyo3["result"]),
                    "matvec_padded face parity",
                );
                assert_f64_bitidentical(&got, &flat_f64(&pyo3["result"]), "matvec face bytes");
                assert_f64_bitidentical(
                    &got_dirty,
                    &flat_f64(&pyo3["result_dirty"]),
                    "matvec dirty face bytes",
                );
            }
        }
    }
}

